import{c as a,Q as d,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const S=JSON.parse('{"title":"Load2DBitMode","description":"","frontmatter":{},"headers":[{"level":1,"title":"Load2DBitMode","slug":"load2dbitmode"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/LoadData/Load2DBitMode.md","filePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/LoadData/Load2DBitMode.md"}'),s={name:"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/LoadData/Load2DBitMode.md"};function i(o,t,r,p,l,c){return d(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="load2dbitmode" tabindex="-1">Load2DBitMode <a class="header-anchor" href="#load2dbitmode" aria-label="Permalink to &quot;Load2DBitMode&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>x</td></tr><tr><td>Kirin 9030</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>Load2D支持如下数据通路的搬运：</p><p>GM-&gt;A1; GM-&gt;B1; GM-&gt;A2; GM-&gt;B2;</p><p>A1-&gt;A2; B1-&gt;B2。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;TPosition Dst, TPosition Src, typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void LoadData(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src,const Load2DBitModeParam&amp; loadDataParam)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>源操作数和目的操作数的数据类型。 Ascend 950PR/Ascend 950DT，仅支持A1-&gt;A2、B1-&gt;B2，支持数据类型为：half/bfloat16_t/uint32_t/int32_t/float/uint8_t/int8_t/fp8_e4m3fn_t/fp8_e5m2_t/hifloat8_t/fp4x2_e2m1_t/fp4x2_e1m2_t</td></tr><tr><td>Src</td><td>源操作数存储的逻辑位置（TPosition），仅Load2DBitMode接口使用。</td></tr><tr><td>Dst</td><td>目的操作数存储的逻辑位置（TPosition），仅Load2DBitMode接口使用。</td></tr></tbody></table><p><strong>表 2</strong> 通用参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。 数据连续排列顺序由目的操作数所在TPosition决定，具体约束如下： A2：ZZ格式/NZ格式；对应的分形大小为16 * (32B / sizeof(T))。B2：ZN格式；对应的分形大小为 (32B / sizeof(T)) * 16。A1/B1：无格式要求，一般情况下为NZ格式。NZ格式下，对应的分形大小为16 * (32B / sizeof(T))。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor或GlobalTensor。 数据类型需要与dst保持一致。</td></tr><tr><td>loadDataParams</td><td>输入</td><td>LoadData参数结构体，类型为： Load2DBitModeParam，具体参考表3。 上述结构体参数定义请参考\${INSTALL_DIR}/include/ascendc/basic_api/interface/kernel_struct_mm.h，\${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。</td></tr></tbody></table><p><strong>表 3</strong> Load2DBitModeParam类参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>config0</td><td>uint64_t类型，与Load2DBitModeConfig0位域（bit-field）结构体类型参数config0BitMode组成联合体（union），初始化为0，可以使用类对象的GetConfig0()函数获取其值。</td></tr><tr><td>config0BitMode</td><td>Load2DBitModeConfig0位域（bit-field）结构体类型，参数参考表4，与config0组成联合体（union）。</td></tr><tr><td>config1</td><td>uint64_t类型，与Load2DBitModeConfig1位域（bit-field）结构体类型参数config1BitMode组成联合体（union），初始化为0，可以使用类对象的GetConfig1()函数获取其值。</td></tr><tr><td>config1BitMode</td><td>Load2DBitModeConfig1位域（bit-field）结构体类型，参数参考表5，与config1组成联合体（union）。</td></tr><tr><td>ifTranspose</td><td>是否启用转置功能，对每个分形矩阵进行转置，默认为false。含义与LoadData2DParamsV2结构体中的同名参数含义相同，具体参考表4。 true：启用false：不启用 注意：只有A1-&gt;A2和B1-&gt;B2通路才能使能转置。使能转置功能时，支持的数据类型约束如下： 源操作数、目的操作数支持b4、b8、b16、b32数据类型。</td></tr></tbody></table><p>Load2DBitModeParam类参数设计思想说明：</p><p>联合体（union）是一种特殊的数据结构，允许在相同的内存位置存储不同的数据类型。union的所有成员共享同一块内存空间，大小由最大成员决定，同一时间只能使用一个成员。</p><p>位域（bit-field）是一种特殊的类成员，允许精确控制结构体中成员变量所占用的内存位数。结构体中成员变量从上到下对应内存中从低位到高位。</p><p>Load2DBitModeParam类使用union与bit-field方法，采用bit位表达参数类型，使用bit-field结构体自动处理入参的bit位数，并利用union的特性实现多参数融合传递，仅需传递一个入参即可包含全部所需信息，对应底层接口仅需要接收一个参数。同时，当需要修改参数中某一bit位的值时，仅需要通过循环和位运算即可实现，不需要重新传入参数，减少了scalar计算，实现性能提升。</p><p>Load2DBitModeParam类可以直接使用LoadData2DParamsV2结构体类型对象初始化：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LoadData2DParamsV2 loadDataParams;</span></span>
<span class="line"><span>loadDataParams.mStartPosition = 0;</span></span>
<span class="line"><span>loadDataParams.kStartPosition = 0;</span></span>
<span class="line"><span>loadDataParams.mStep = xxx;</span></span>
<span class="line"><span>loadDataParams.kStep = xxx;</span></span>
<span class="line"><span>loadDataParams.srcStride = xxx;</span></span>
<span class="line"><span>loadDataParams.dstStride = xxx;</span></span>
<span class="line"><span>loadDataParams.sid = 0;</span></span>
<span class="line"><span>loadDataParams.ifTranspose = false;</span></span>
<span class="line"><span>Load2DBitModeParam params(loadDataParams);  // 直接使用LoadData2DParamsV2结构体类型对象初始化</span></span></code></pre></div><p>也可以使用各参数的Set函数修改参数值，并且由于使用了联合体，还可以对congfig0和config1直接进行逐bit位修改来修改参数。</p><p><strong>表 4</strong> Load2DBitModeConfig0结构体参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>mStartPosition</td><td>以M*K矩阵为例，源矩阵M轴方向的起始位置，单位为16个元素。 该参数是位域结构体的最低位参数，占用16bit，可以使用Load2DBitModeParam类对象的SetMStartPosition()函数设置其值，使用GetMStartPosition()函数获取其值，具体参考表6。</td></tr><tr><td>kStartPosition</td><td>以M*K矩阵为例，源矩阵K轴方向的起始位置，单位为32B。 该参数是位域结构体的第二低位参数，占用16bit，可以使用Load2DBitModeParam类对象的SetKStartPosition()函数设置其值，使用GetKStartPosition()函数获取其值，具体参考表6。</td></tr><tr><td>mStep</td><td>以M*K矩阵为例，源矩阵M轴方向搬运长度，单位为16 element。取值范围：mStep∈[0, 255]。 通过ifTranspose参数启用转置功能时，mStep除需满足 [0, 255]的取值范围外，还需满足以下额外约束： 当数据类型为b4时，mStep必须是4的倍数；当数据类型为b8时，mStep必须是2的倍数；当数据类型为b16时，mStep必须是1的倍数；当数据类型为b32时，mStep无额外约束。 该参数是位域结构体的第三低位参数，占用8bit，可以使用Load2DBitModeParam类对象的SetMStep()函数设置其值，使用GetMStep()函数获取其值，具体参考表6。</td></tr><tr><td>kStep</td><td>以M*K矩阵为例，源矩阵K轴方向搬运长度，单位为32B。取值范围：kStep∈[0, 255]。 通过ifTranspose参数启用转置功能时，kStep除需满足[0,255]的取值范围外，还需满足以下额外约束： 当数据类型为b4、b8或b16时，kStep没有额外约束；当数据类型为b32时，kStep必须是2的倍数。 该参数是位域结构体的最高位参数，占用8bit，可以使用Load2DBitModeParam类对象的SetKStep()函数设置其值，使用GetKStep()函数获取其值，具体参考表6。</td></tr></tbody></table><p>Load2DBitModeConfig0结构体参数的含义与LoadData2DParamsV2结构体中的同名参数含义相同，具体参考<a href="./Load2D.html#table49630346128">表4</a>。</p><p><strong>表 5</strong> Load2DBitModeConfig1结构体参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>srcStride</td><td>以M*K矩阵为例，源矩阵K方向前一个分形起始地址与后一个分形起始地址的间隔，单位：512B。 该参数是位域结构体的最低位参数，占用16bit，可以使用Load2DBitModeParam类对象的SetSrcStride()函数设置其值，使用GetSrcStride()函数获取其值，具体参考表6。</td></tr><tr><td>dstStride</td><td>以M*K矩阵为例，目标矩阵K方向前一个分形起始地址与后一个分形起始地址的间隔，单位：512B。 该参数是位域结构体的最高位参数，占用16bit，可以使用Load2DBitModeParam类对象的SetDstStride()函数设置其值，使用GetDstStride()函数获取其值，具体参考表6。</td></tr></tbody></table><p>Load2DBitModeConfig1结构体参数的含义与LoadData2DParamsV2结构体中的同名参数含义相同，具体参考<a href="./Load2D.html#table49630346128">表4</a>。</p><p><strong>表 6</strong> Load2DBitModeParam类成员函数说明</p><table tabindex="0"><thead><tr><th>函数名称</th><th>功能</th></tr></thead><tbody><tr><td>void SetMStartPosition(uint32_t mStartPosition_)</td><td>将Load2DBitModeConfig0结构体参数mStartPosition的值设置为mStartPosition_。</td></tr><tr><td>void SetKStartPosition(uint32_t kStartPosition_)</td><td>将Load2DBitModeConfig0结构体参数kStartPosition的值设置为kStartPosition_。</td></tr><tr><td>void SetMStep(uint16_t mStep_)</td><td>将Load2DBitModeConfig0结构体参数mStep的值设置为mStep_。</td></tr><tr><td>void SetKStep(uint16_t kStep_)</td><td>将Load2DBitModeConfig0结构体参数kStep的值设置为kStep_。</td></tr><tr><td>void SetSrcStride(int32_t srcStride_)</td><td>将Load2DBitModeConfig1结构体参数srcStride的值设置为srcStride_。</td></tr><tr><td>void SetDstStride(uint16_t dstStride_)</td><td>将Load2DBitModeConfig1结构体参数dstStride的值设置为dstStride_。</td></tr><tr><td>uint32_t GetMStartPosition() const</td><td>获取Load2DBitModeConfig0结构体参数mStartPosition的值。</td></tr><tr><td>uint32_t GetKStartPosition() const</td><td>获取Load2DBitModeConfig0结构体参数kStartPosition的值。</td></tr><tr><td>uint16_t GetMStep() const</td><td>获取Load2DBitModeConfig0结构体参数mStep的值。</td></tr><tr><td>uint16_t GetKStep() const</td><td>获取Load2DBitModeConfig0结构体参数kStep的值。</td></tr><tr><td>int32_t GetSrcStride() const</td><td>获取Load2DBitModeConfig1结构体参数srcStride的值。</td></tr><tr><td>uint16_t GetDstStride() const</td><td>获取Load2DBitModeConfig1结构体参数dstStride的值。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="./../../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li></ul><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;kernel_operator.h&quot;</span></span>
<span class="line"><span>uint16_t C1 = 2;</span></span>
<span class="line"><span>uint16_t H = 4, W = 4;</span></span>
<span class="line"><span>uint8_t Kh = 2, Kw = 2;</span></span>
<span class="line"><span>uint16_t Cout = 16;</span></span>
<span class="line"><span>uint16_t C0 = 16;</span></span>
<span class="line"><span>uint8_t dilationH = 2, dilationW = 2;</span></span>
<span class="line"><span>uint8_t padTop = 1, padBottom = 1, padLeft = 1, padRight = 1;</span></span>
<span class="line"><span>uint8_t strideH = 1, strideW = 1;</span></span>
<span class="line"><span>uint16_t coutBlocks, ho, wo, howo, howoRound;</span></span>
<span class="line"><span>uint32_t featureMapA1Size, weightA1Size, featureMapA2Size, weightB2Size, dstSize, dstCO1Size;</span></span>
<span class="line"><span>uint8_t padList[4] = {padLeft, padRight, padTop, padBottom};</span></span>
<span class="line"><span>featureMapA2Size = howoRound * (C1 * Kh * Kw * C0);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fmRepeat = featureMapA2Size / (16 * C0);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>LoadData2DParamsV2 param = { padList, H, W, 0, 0, 0, -1, -1, strideW, strideH, Kw, Kh, dilationW, dilationH, 1, 0, fmRepeat, 0, (half)(0)};</span></span>
<span class="line"><span>Load2DBitModeParam paramBitMode(param); </span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; featureMapA1 = inQueueFmA1.DeQue&lt;half&gt;();</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; featureMapA2 = inQueueFmA2.AllocTensor&lt;half&gt;();</span></span>
<span class="line"><span>AscendC::LoadData&lt;A2, A1, half&gt;(featureMapA2, featureMapA1, paramBitMode);</span></span>
<span class="line"><span>inQueueFmA2.EnQue&lt;half&gt;(featureMapA2);</span></span>
<span class="line"><span>inQueueFmA1.FreeTensor(featureMapA1);</span></span></code></pre></div>`,37)])])}const u=a(s,[["render",i]]);export{S as __pageData,u as default};
